INSERT INTO "GuestbookEntry" ("name","message","color","approved","createdAt") SELECT * FROM (VALUES
  ('Wanderer_07','Across dimensions, the orbit holds. Salam chaos dari ujung galaksi.','#ff4d4d',true,NOW()),
  ('Pixel Phantom','Situs ini bikin nostalgia SMK banget. Neo-brutalism for the win.','#00e5ff',true,NOW()),
  ('Orbit Guest','Seven souls, one gravity. Tetap bersama walau terpisah ratusan parsec.','#d4ff00',true,NOW()),
